        "name": "Alien Shadow Map (Deduplication Normalization)",
        "pseudocode": "function AlienShadow(L):\n    seen <- empty set\n    result <- empty list\n    for i in L:\n        if i not in seen:\n            seen <- seen union {i}\n            result.append(i)\n    return result\n\nTime: O(n) expected with hash set\nSpace: O(n)",
        "code": "def alien_shadow(exponents):\n    \"\"\"Order-preserving deduplication \u2014 the normalization invisible to idempotent civilizations.\"\"\"\n    seen = set()\n    result = []\n    for i in exponents:\n        if i not in seen:\n            seen.add(i)\n            result.append(i)\n    return result\n\n# Example\nprint(alien_shadow([0, 1, 0, 1, 1]))  # [0, 1]\nprint(alien_shadow([3, 1, 4, 1, 5, 9, 2, 6, 5]))  # [3, 1, 4, 5, 9, 2, 6]",
        "code_file": "visualizations/alien_mathematics_what_theorems_would_non_carbon_l_alien_shadow_map_deduplication_normaliza.py"
