        "name": "Semiring Identity Tester",
        "pseudocode": "function TestDedupIdentity(semirings, test_lists, test_points):\n    for S in semirings:\n        holds <- true\n        for L in test_lists:\n            shadow <- AlienShadow(L)\n            for x in test_points:\n                if S.eval(x, L) != S.eval(x, shadow):\n                    holds <- false\n                    report counterexample (S, L, x)\n                    break\n        report (S.name, holds)\n\nTime: O(|semirings| * |test_lists| * |test_points| * max_list_len)",
        "code": "def eval_nat(x, exponents):\n    return sum(x ** i for i in exponents)\n\ndef eval_tropical(x, exponents):\n    return max((x ** i for i in exponents), default=0)\n\ndef alien_shadow(L):\n    seen, result = set(), []\n    for i in L:\n        if i not in seen:\n            seen.add(i); result.append(i)\n    return result\n\ntest_lists = [[0, 0], [1, 1, 1], [0, 1, 0], [2, 3, 2, 3]]\nfor L in test_lists:\n    shadow = alien_shadow(L)\n    for x in [1, 2, 3]:\n        nat_eq = eval_nat(x, L) == eval_nat(x, shadow)\n        trop_eq = eval_tropical(float(x), L) == eval_tropical(float(x), shadow)\n        print(f\"L={L}, x={x}: NAT {\"=\" if nat_eq else \"!=\"}, TROP {\"=\" if trop_eq else \"!=\"}\")",
